            ${checksums['kapp-linux-amd64']}  ./kapp-linux-amd64
            ${checksums['kapp-linux-arm64']}  ./kapp-linux-arm64
            ${checksums['kapp-windows-amd64.exe']}  ./kapp-windows-amd64.exe`

